-- 030_access_requests.sql -- Solicitação de conta com fluxo de aprovação (landing split-screen + painel admin).  -- Colunas de controle de aprovação na tabela users. ALTER TABLE users   ADD COLUMN IF NOT EXISTS approval_status text NOT NULL DEFAULT 'active'     CHECK (approval_status IN ('active', 'pending', 'rejected')),   ADD COLUMN IF NOT EXISTS company text,   ADD COLUMN IF NOT EXISTS request_message text;  -- Histórico de solicitações: permite rastrear aprovações/recusas e re-solicitações. CREATE TABLE IF NOT EXISTS access_requests (   id uuid PRIMARY KEY DEFAULT gen_random_uuid(),   user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,   name text NOT NULL,   email text NOT NULL,   company text,   message text,   status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),   reviewed_by uuid REFERENCES users(id) ON DELETE SET NULL,   reviewed_at timestamptz,   created_at timestamptz NOT NULL DEFAULT now() );  CREATE INDEX IF NOT EXISTS idx_access_requests_user ON access_requests(user_id); CREATE INDEX IF NOT EXISTS idx_access_requests_status ON access_requests(status);